+    this.treasureGraphics = this.add.graphics().setDepth(1.6);
+    this.drawTreasure(now, minimapLeft);
+  private drawTreasure(now: number, minimapLeft: number): void {
+    const graphics = this.treasureGraphics;
+    graphics.clear();
+    const claim = this.view.claim();
+    const route = claim !== undefined && claim.routeKnown ? claim : undefined;
+    if (route !== undefined) {
+      const x = route.routeX * PIXELS_PER_SUB_UNIT;
