+        if (Math.hypot(x - ox, y - oy) > radius) {
+          const angle = Math.atan2(y - oy, x - ox);
+          const near = 16 * ART_SCALE;
+          const far = 26 * ART_SCALE;
+          graphics.fillStyle(TREASURE_COLOR, 0.95);
+          graphics.fillTriangle(
+            ox + Math.cos(angle) * far,
+            oy + Math.sin(angle) * far,
+            ox + Math.cos(angle + 0.3) * near,
+            oy + Math.sin(angle + 0.3) * near,
+            ox + Math.cos(angle - 0.3) * near,
+            oy + Math.sin(angle - 0.3) * near,
+          );
+        }
+      }
+    }
+    const claiming: string[] = [];
+    for (const [id, held] of this.view.claimingShips()) {
+      const at = this.view.renderPosition(id, now);
+      if (at === undefined) continue;
+      claiming.push(id);
+      const total = claim?.claimTotal || 200;
+      const x = at.x * PIXELS_PER_SUB_UNIT;
+      const y = at.y * PIXELS_PER_SUB_UNIT;
+      graphics.lineStyle(2, TREASURE_COLOR, 0.35);
+      graphics.strokeCircle(x, y, 16 * ART_SCALE);
+      graphics.lineStyle(4, TREASURE_COLOR, 1);
+      graphics.beginPath();
+      graphics.arc(x, y, 16 * ART_SCALE, -Math.PI / 2, -Math.PI / 2 + 2 * Math.PI * Math.min(1, held / total), false);
+      graphics.strokePath();
+    }
+    const report = `${route === undefined ? "" : `${route.routeX},${route.routeY},${route.routeActive}`}|${claiming.sort().join(",")}`;
+    if (report !== this.lastTreasureReport) {
+      this.lastTreasureReport = report;
+      this.report.dataset["route"] = route === undefined ? "" : `${route.routeX},${route.routeY},${route.routeActive}`;
+      this.report.dataset["claiming"] = claiming.join(",");
+    }
+  }
