import json, subprocess, sys, os, time
S = "/home/agentops/.claude/jobs/75fe6abc/tmp/scratch"
OUT = "/home/agentops/.claude/jobs/75fe6abc/tmp/mut"
muts = json.load(open(sys.argv[1]))
results_path = sys.argv[2]
done = {}
if os.path.exists(results_path):
    for line in open(results_path):
        r = json.loads(line); done[r["id"]] = r
for m in muts:
    if m["id"] in done: continue
    edits = m["edits"]
    originals = {}
    ok = True
    for e in edits:
        p = os.path.join(S, e["file"])
        if p not in originals: originals[p] = open(p).read()
        cur = open(p).read()
        n = cur.count(e["old"])
        if n != 1:
            ok = False; err = f"{e['file']}: old occurs {n} times"; break
        open(p, "w").write(cur.replace(e["old"], e["new"]))
    if not ok:
        for p, s in originals.items(): open(p, "w").write(s)
        r = {"id": m["id"], "error": err}
    else:
        jf = os.path.join(OUT, m["id"] + ".json")
        if os.path.exists(jf): os.remove(jf)
        cmd = ["npx", "vitest", "run"] + [a for pr in m["projects"] for a in ("--project", pr)] + m["files"] + ["--reporter=json", "--outputFile=" + jf]
        t = time.time()
        proc = subprocess.run(cmd, cwd=S, capture_output=True, text=True, timeout=600)
        for p, s in originals.items(): open(p, "w").write(s)
        failed = []
        try:
            data = json.load(open(jf))
            for f in data["testResults"]:
                for a in f["assertionResults"]:
                    if a["status"] != "passed": failed.append(os.path.basename(f["name"]) + ": " + a["title"])
                if f.get("status") == "failed" and not any(a["status"] != "passed" for a in f["assertionResults"]):
                    failed.append(os.path.basename(f["name"]) + ": (file failed) " + (f.get("message") or "")[:200])
        except Exception as ex:
            failed.append("NO JSON: " + str(ex) + proc.stdout[-500:] + proc.stderr[-500:])
        r = {"id": m["id"], "failed": failed, "secs": round(time.time() - t)}
    with open(results_path, "a") as fh: fh.write(json.dumps(r) + "\n")
    print(r["id"], "->", r.get("error") or (r["failed"] if r["failed"] else "SURVIVED"), flush=True)
EOF
echo ok

